<script setup>
import accountGet from './components/accountGet.vue'
import { ref, onMounted } from 'vue'
import { useRouter } from 'vue-router'

const router = useRouter()
const userData = ref({})

onMounted(async () => {
  try {
    const data = await accountGet.methods.getAccount() 
    userData.value = data
  } catch (error) {
    console.error('获取用户数据失败：', error)
    userData.value = {}
  }
})

const goToTable = (tableName) => {
  router.push({ name: tableName })
}

const handleUserLink = (link) => {
  if (link.startsWith('/') || !link.includes('http')) {
    goToTable(link)
  } else {
    window.open(link, '_blank')
  }
}
</script>

<template>
  <div class="user-container">
    <div v-for="(userList, category) in userData" :key="category" class="category-section">
      <h2 class="category-title">{{ category }}</h2>
      <div class="user-card-container">
        <div 
          class="user-card" 
          v-for="(user, index) in userList" 
          :key="index"
          @click="handleUserLink('https://space.bilibili.com/' + user[1])"
        >
          <div class="user-info">
            <h3 class="user-name">@{{ user[0] }}</h3>
            <p class="user-desc">{{ user[2] || '' }}</p>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<style scoped>
.user-container {
  max-width: 1500px;
  margin: 0 auto;
  padding: 20px;
}

.category-section {
  margin-bottom: 40px;
}

.category-title {
  font-size: 28px;
  color: #6c90e5;
  margin: 0 0 20px 0;
  padding-bottom: 10px;
  border-bottom: 2px solid #6c90e5;
}

.user-card-container {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(20%, 1fr));
  gap: 20px;
  padding: 10px 0;
}

.user-card {
  display: flex;
  align-items: center;
  gap: 15px;
  padding: 15px;
  background-color: var(--color-bg-sub);
  cursor: pointer;
  transition: all 0.3s ease;
}

.user-card:hover {
  border: 1px solid #6c90e5;
}

.user-info {
  flex: 1;
  overflow: hidden;
}

.user-name {
  margin: 0 0 8px 0;
  font-size: 22px;
  color: #6c90e5;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.user-desc {
  margin: 0;
  font-size: 15px;
  color: #d2d2d2;
  line-height: 1.4;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
</style>