<script setup>
import { ref, onMounted } from 'vue'
import charterGUI from './components/charterGUI.vue'
import charterGet from './components/charterGet.vue'

const charterList = ref(null)
const isLoading = ref(true)
const errorMsg = ref('')

onMounted(async () => {
  try {
    const charterData = await charterGet.methods.getCharter('/files/infos/charters.json')
    charterList.value = charterData
    errorMsg.value = ''
  } catch (error) {
    console.error('谱师列表加载失败：', error)
    errorMsg.value = '谱师列表加载失败，请刷新重试'
  } finally {
    isLoading.value = false
  }
})
</script>

<template>
  <div class="table-container">
    <div v-if="isLoading" class="empty-tip">
      正在加载谱师列表
    </div>
    
    <div v-else-if="errorMsg" class="empty-tip error">
      {{ errorMsg }}
    </div>
    
    <div v-else-if="charterList" class="charter-list">
      <charterGUI 
        :card-list="charterList"
        :columns="5"
        :gap="20"
      >
        <template #default="{ cardData }">
          <charterCard :chart-info="cardData" />
        </template>
      </charterGUI>
    </div>
    
    <div v-else class="empty-tip">
      暂无谱师列表数据
    </div>
  </div>
</template>

<style scoped>
  .charter-list {
    margin-top: 20px;
  }

  .empty-tip {
    display: flex;
    justify-content: center;
    align-items: center;
    height: 200px;
    color: var(--color-text-sub);
    font-size: 16px;
  }

  .empty-tip.error {
    color: var(--color-text-error);
  }
</style>