<template>
  <div class="song-wrapper">
    <div class="card-grid">

      <div
        class="stage-section"
        v-for="(stageData, stageName) in safeSongList"
        :key="stageName"
      >
        <div class="match-main-title" :style="{ color: textColor }">
          {{ stageName }}
        </div>

        <div
          class="song-card"
          :style="{ background: mainColor }"
          v-for="(groupData, groupName) in stageData"
          :key="`${stageName}-${groupName}`"
        >
          <div class="group-item">
            <div class="group-sub-title" :style="{ color: textColor }">
              {{ stageName }}
            </div>
            <div class="group-title" :style="{ color: textColor }">
              {{ groupName }}
            </div>
            <div class="divider" :style="{ backgroundColor: textColor + '30' }"></div>

            <div class="player-list">
              <div
                class="player-item"
                :style="{ borderColor: textColor + '30' }"
                v-for="player in getPlayerList(groupData)"
                :key="player.uid"
              >
                <div class="player-left">
                  <div class="player-name" :style="{ color: textColor }">
                    {{ player.name }}
                  </div>
                  <div class="player-uid" :style="{ color: textColor, opacity: 0.8 }">
                    @{{ player.id }}
                  </div>
                </div>

                <div class="player-right">
                  <div class="total-score" :style="{ color: textColor }">
                    {{ player.total_score }}
                  </div>
                  <span
                    class="status-tag"
                    :class="{ pass: player.result === 'T', fail: player.result === 'F' }"
                    :style="{ color: mainColor }"
                  >
                    {{ player.status }}
                  </span>
                </div>
              </div>
            </div>
            <div class="divider" :style="{ backgroundColor: textColor + '30' }"></div>

            <div class="table-wrapper">
              <table class="score-table">
                <thead>
                  <tr>
                    <th :style="{ color: textColor }">谱面</th>
                    <th
                      v-for="player in getPlayerList(groupData)"
                      :key="player.uid"
                      :style="{ color: textColor }"
                    >
                      {{ player.name }}
                    </th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="(song, idx) in getChartsList(groupData)" :key="idx">
                    <td :style="{ color: textColor }">
                      {{ song }}
                    </td>
                    <td
                      v-for="player in getPlayerList(groupData)"
                      :key="player.uid"
                      :style="{ color: textColor }"
                    >
                      {{ player.scores?.[idx] ?? 0 }}
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>

    </div>
  </div>
</template>

<script setup>
import { computed } from 'vue'
const props = defineProps({
  songList: { type: Object, required: true },
  mainColor: { type: String, required: true },
  textColor: { type: String, required: true }
})

const safeSongList = computed(() => {
  return props.songList && typeof props.songList === 'object' ? props.songList : {}
})

const getPlayerList = (groupData) => {
  if (!groupData?.players || typeof groupData.players !== 'object') return []
  return Object.values(groupData.players)
    .map(item => ({
      ...item?.player,
      scores: item?.scores || [],
      total_score: item?.total_score ?? 0,
      result: item?.result ?? '',
      status: item?.status ?? '未知'
    }))
    .sort((a, b) => {
      const sa = Number(a.total_score) || 0
      const sb = Number(b.total_score) || 0
      return sb - sa
    })
}

const getChartsList = (groupData) => {
  return groupData?.charts || []
}
</script>

<style scoped>
.song-wrapper {
  width: 100%;
}
.card-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
}

.stage-section {
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: 100%;
}

.match-main-title {
  width: 100%;
  font-size: 38px;
  font-weight: bold;
  padding: 8px 0;
  text-align: center;
}

.song-card {
  width: 100%;
  padding: 24px;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.15);
}

.group-title {
  font-size: 24px;
  font-weight: 600;
  margin-bottom: 16px;
  text-align: center;
  color: inherit;
}
.group-sub-title {
  font-size: 18px;
  font-weight: 600;
  text-align: center;
  color: inherit;
}
.divider {
  height: 3px;
  margin: 15px 0;
}

.player-list {
  margin-bottom: 2px;
}
.player-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  margin-bottom: 3px;
}
.player-left {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.player-name {
  font-size: 24px;
  font-weight: 600;
}
.player-uid {
  font-size: 16px;
}
.player-right {
  display: flex;
  align-items: center;
  gap: 0;
  width: 350px;
  justify-content: space-between;
}
.total-score {
  font-size: 24px;
  font-weight: bold;
  width: 100px;
  text-align: right;
}

.table-wrapper {
  width: 100%;
  overflow-x: auto;
  display: flex;
  justify-content: center;
}
.score-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 20px;
  table-layout: fixed;
}
.score-table th:first-child,
.score-table td:first-child {
  width: 600px;
  white-space: nowrap;
  text-align: left;
}
.score-table th:not(:first-child),
.score-table td:not(:first-child) {
  width: auto;
  flex: 1;
}
.score-table th,
.score-table td {
  padding: 12px 14px;
  text-align: center;
  border: none;
}

.status-tag {
  display: inline-block;
  padding: 8px 16px;
  font-weight: bold;
  font-size: 24px;
  min-width: 180px;
  text-align: center;
}
.status-tag.pass {
  background-color: #4cd964;
}
.status-tag.fail {
  background-color: #e5332a;
}
</style>