<template>
  <div class="card-container">
    <div v-for="({ key: charterName, value: songList }, index) in sortedCardList" :key="charterName" class="charter-group">
      <div class="charter-title">{{ charterName }}</div>
      <div class="card-grid">
        <div
          v-for="(item, idx) in getGroupSortedCards(songList)"
          :key="idx"
          class="chart-card"
        >
          <div class="card-cover">
            <img :src="item.songData.cover" :alt="item.songData.name" class="cover-img" />
            <div class="diff-badge" :style="{ backgroundColor: item.diffData.color }">
              {{ item.diffKey }} Lv.{{ item.diffData.lvl }}
            </div>
          </div>
          <div class="card-info">
            <div class="info-title">{{ item.diffData.charter }}</div>
            <div class="info-charter">{{ item.diffData.tcharter }}</div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { computed } from 'vue';

const props = defineProps({
  cardList: {
    type: Object,
    required: true
  }
});

const sortedCardList = computed(() => {
  return Object.entries(props.cardList).map(([key, value]) => ({ key, value }));
});

const getGroupSortedCards = (songList) => {
  const items = []
  Object.values(songList).forEach((songData) => {
    const { name, cover, ...difficulties } = songData
    Object.entries(difficulties).forEach(([diffKey, diffData]) => {
      items.push({ songData, diffKey, diffData })
    })
  })
  return items.sort((a, b) => {
    const qa = String(a.diffData.lvl).includes("?")
    const qb = String(b.diffData.lvl).includes("?")
    if (qa && !qb) return -1
    if (!qa && qb) return 1
    const na = Number(a.diffData.lvl) || 0
    const nb = Number(b.diffData.lvl) || 0
    return nb - na
  })
}
</script>

<style scoped>
.card-container {
  width: 100%;
}

.charter-group {
  margin-bottom: 45px;
}

.charter-title {
  font-size: 22px;
  font-weight: bold;
  color: #ffffff;
  background: #2a2d2f;
  padding: 12px 16px;
  margin-bottom: 16px;
  text-align: center;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 14px;
}

.chart-card {
  display: flex;
  height: 150px;
  background-color: #212426;
  overflow: hidden;
  color: #ffffff;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.2);
}

.card-cover {
  aspect-ratio: 256 / 135;
  position: relative;
  flex-shrink: 0;
}

.cover-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.diff-badge {
  position: absolute;
  right: 8px;
  bottom: 8px;
  padding: 8px 12px;
  font-size: 13px;
  font-weight: 600;
  color: #fff;
  min-width: 80px;  
  text-align: center;
}

.card-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 0 12px;
  font-size: 18px;
  text-align: center;
}

.info-title {
  font-weight: bold;
  font-size: 22px;
  margin-bottom: 4px;
}

.info-charter {
  line-height: 1.4;
  font-size: 16px;
  word-break: break-all;
}
</style>